(()=>{
 const languageButton=document.querySelector('#case-language');
 let lang='en';try {lang=localStorage.getItem('portfolio-language')==='zh'?'zh':'en'}catch{}
 function language(value){lang=value;document.documentElement.lang=lang==='zh'?'zh-Hans':'en';document.body.dataset.language=lang;document.querySelectorAll('[data-zh][data-en]').forEach(e=>e.textContent=e.dataset[lang]);languageButton.textContent=lang==='zh'?'EN':'中';languageButton.setAttribute('aria-label',lang==='zh'?'切换到英文':'Switch to Chinese');try {localStorage.setItem('portfolio-language',lang)}catch{}}
 language(lang);languageButton.addEventListener('click',()=>{language(lang==='zh'?'en':'zh');themeLabel()});
 const theme=document.querySelector('#theme');try{document.body.dataset.theme=localStorage.getItem('portfolio-theme')||'light'}catch{}
 function themeLabel(){theme.setAttribute('aria-label',lang==='zh'?'切换深浅主题':'Switch light or dark theme');theme.textContent=document.body.dataset.theme==='dark'?'☀':'☾'}themeLabel();theme.addEventListener('click',()=>{document.body.dataset.theme=document.body.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('portfolio-theme',document.body.dataset.theme)}catch{}themeLabel()});
 const dialog=document.querySelector('#lightbox');let opener;
 document.querySelectorAll('.zoom').forEach(button=>button.addEventListener('click',()=>{opener=button;const src=button.querySelector('img');const image=dialog.querySelector('img');image.src=src.src;image.alt=src.alt;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>opener?.focus());
 document.querySelectorAll('[data-deck]').forEach(deck=>{const rail=deck.querySelector('.step-rail');const prev=deck.querySelector('[data-prev]');const next=deck.querySelector('[data-next]');const cards=[...rail.children];const position=deck.querySelector('[data-position]');const reduced=matchMedia('(prefers-reduced-motion:reduce)');function active(){if(rail.scrollLeft>=rail.scrollWidth-rail.clientWidth-2)return cards.length-1;return cards.reduce((best,card,i)=>Math.abs(card.offsetLeft-cards[0].offsetLeft-rail.scrollLeft)<Math.abs(cards[best].offsetLeft-cards[0].offsetLeft-rail.scrollLeft)?i:best,0)}function update(){const i=active();position.textContent=`${i+1} / ${cards.length}`;prev.disabled=rail.scrollLeft<=2;next.disabled=rail.scrollLeft>=rail.scrollWidth-rail.clientWidth-2}function move(dir){const i=Math.max(0,Math.min(cards.length-1,active()+dir));rail.scrollTo({left:cards[i].offsetLeft-cards[0].offsetLeft,behavior:reduced.matches?'instant':'smooth'})}prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));rail.addEventListener('scroll',update,{passive:true});rail.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});new ResizeObserver(update).observe(rail);update()});
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)document.querySelectorAll('.case-index nav a').forEach(a=>a.hash==='#'+entry.target.id?a.setAttribute('aria-current','location'):a.removeAttribute('aria-current'))})},{rootMargin:'-5% 0px -65% 0px'});document.querySelectorAll('.case-section').forEach(s=>observer.observe(s));
 document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==v)other.pause()})));
 document.querySelectorAll('.motion-media').forEach(figure=>{const video=figure.querySelector('video'),button=figure.querySelector('.media-play');if(!video||!button)return;const sync=()=>{button.dataset.zh=video.paused?'播放':'暂停';button.dataset.en=video.paused?'Play':'Pause';button.textContent=lang==='zh'?button.dataset.zh:button.dataset.en;button.setAttribute('aria-pressed',String(!video.paused))};button.addEventListener('click',()=>{if(video.paused){video.play().catch(()=>sync())}else{video.pause()}});video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('ended',sync);sync()});
})();
